const qzData=[{"q":"¿Cuántos supuestos pide el teorema que promete eficiencia, y quién los escribió?","o":["a) Dos, y los escribieron sus críticos","b) Cuatro, y los escribieron quienes demostraron el teorema","c) Ninguno: el teorema no tiene supuestos","d) Diez, y están en disputa"],"c":1},{"q":"Una externalidad es…","o":["a) Un impuesto mal calculado","b) Un precio demasiado alto","c) Una importación","d) Un costo que recae sobre quien no participó en el intercambio"],"c":3},{"q":"La contracrítica obligada a Pigou la escribió…","o":["a) Akerlof, en 1970","b) Minsky, en 1986","c) Coase, en 1960","d) Manning, en 2003"],"c":2},{"q":"La advertencia que el propio Coase dejó por escrito en 1988 es que…","o":["a) Los impuestos siempre funcionan","b) Su argumento vale donde negociar cuesta poco, y rechazó la versión de manual","c) Su argumento no valía para nada","d) Pigou tenía razón en todo"],"c":1},{"q":"El monopsonio es el caso en que…","o":["a) El único que compra paga de menos, sin violar ninguna ley","b) El único que vende cobra de más","c) Hay muchos compradores y muchos vendedores","d) El Estado fija los precios"],"c":0},{"q":"¿Por qué la disputa Card y Krueger contra Neumark y Wascher se enseña como disputa?","o":["a) Porque nadie la ha estudiado","b) Porque es muy antigua","c) Porque midieron el mismo tipo de caso y llegaron a resultados distintos, y sigue abierta","d) Porque ya se resolvió a favor de Card y Krueger"],"c":2},{"q":"En el mercado de los limones de Akerlof, ¿qué pasa con los productos buenos?","o":["a) Suben de precio","b) Se venden primero","c) Los compra el Estado","d) Se retiran, porque a precio de promedio no conviene venderlos"],"c":3},{"q":"Lo que Greenwald y Stiglitz demostraron en 1986 es que…","o":["a) Con información imperfecta los mercados no son eficientes por regla","b) La información siempre es perfecta","c) Los carros usados son un caso raro","d) Los monopolios no existen"],"c":0},{"q":"La tesis de Minsky es que…","o":["a) La estabilidad incuba inestabilidad","b) Las crisis vienen siempre de afuera","c) El riesgo se puede eliminar","d) Los bancos son innecesarios"],"c":0},{"q":"Cuando se propone una regla para corregir una falla, esta casa exige además…","o":["a) Que la firme un premio Nobel","b) Decir qué cuesta esa regla y a quién, y compararla con la alternativa real","c) Que se aplique en todo el mundo","d) Que sea gratis"],"c":1}];
let qzIdx=0,qzSel=-1,qzDone=false;
function buildQz(){qzIdx=0;qzSel=-1;qzDone=false;showQz();}
