/* ══════════════════════════════════════════════════════════════════
   EL TALLER DE LA MEMORIA · lo que esta misión le presta al aparato
   ══════════════════════════════════════════════════════════════════
   El aparato vive en `js/taller-neuro.js` y `css/taller-neuro.css`, se
   carga DESPUÉS de este archivo, y no sabe nada de fallas de mercado:
   pone el XP variable, el cierre de cuaderno, el repaso espaciado, el
   taller mezclado, el modo Feynman, la dificultad deseable y el panel.
   Lo que sabe de ESTA etapa se lo pasa este bloque, y por eso el
   contenido sigue viviendo con la misión y no en el aparato.
   ══════════════════════════════════════════════════════════════════ */

/* Si el aparato no está cargado (una misión copiada sin él, o el
   archivo que no llegó), el XP vuelve a ser el fijo de siempre y la
   misión sigue entera. El aparato SUSTITUYE esta función al arrancar
   (window.ptsVar); esto es lo que queda si no está. */
function ptsVar(n, motivo) { return pts(n); }

/* El reto de treinta segundos pierde diez en modo difícil. Se pregunta
   cada vez y no se guarda en una variable: el modo se enciende y se
   apaga en mitad de la misión. */
function tallerSegundosReto() { return window.tnDificultad ? 20 : 30; }

/* ── Las tarjetas, del lado del modo difícil ──
   Intercalar tarjetas de la etapa 1 no es relleno: con TODAS las
   tarjetas de esta etapa, «externalidad» acierta media baraja sin
   haber recordado nada, porque el contexto contesta por uno. Mezcladas
   con las de la gran fuga, hay que reconocer primero de qué se está
   hablando, que es lo que la evaluación va a pedir. */
const FC_DE_LA_ETAPA = fcData.slice();
function tallerIntercalaFlash(extra) {
  const baraja = (extra && extra.length) ? _shuffle(FC_DE_LA_ETAPA.concat(extra)) : FC_DE_LA_ETAPA.slice();
  fcData.length = 0;
  baraja.forEach(c => fcData.push(c));
  fcIdx = 0;
  upFC();
  /* xpTracker.fc NO se limpia a propósito: los índices ya no apuntan a
     las mismas tarjetas, y limpiarlo convertiría encender y apagar el
     modo en una máquina de fabricar XP. */
}
/* Encender o apagar el modo difícil cambia los segundos del reto, y el
   número está escrito en TRES sitios de la pantalla: el título, el reloj y
   el cronómetro que corre. Si solo cambiara el que corre, el título seguiría
   prometiendo treinta segundos mientras la partida dura veinte, que es la
   clase de detalle que hace desconfiar del resto. */
function tallerRepintaReto() {
  const seg = tallerSegundosReto();
  const rotulo = document.getElementById('retoSegundosRotulo');
  if (rotulo) rotulo.textContent = seg;
  const reloj = document.getElementById('retoTimer');
  if (reloj && !retoRunning) reloj.textContent = '⏱ ' + seg;
  if (!retoRunning) retoSec = seg;
}

function tallerFlashActual() { return fcIdx; }
function tallerFlashIr(i) { if (i >= 0 && i < fcData.length) { fcIdx = i; upFC(); } }

